test('blocks git push with refspec to main', () => {
  const res = runBashGuard('git push origin HEAD:main');
  assert.strictEqual(res.blocked, true);
});

test('screenMcpSetupPrompt respects configured windows platform', () => {
  const row = S.resolveAll({ platform: 'windows' }).find(r => r.setting.path === 'platform');
  assert.strictEqual(row.value, 'windows');
});

def test_canonical_env_is_root():
    from server.config import config
    assert config.__class__.model_config.get('env_file').endswith('/helpotron/.env')

def test_scope_delimiter_boundary():
    prefixes = ['/api/task']
    assert not check_scope('/api/task_admin', prefixes)

def test_readme_prompt_spelling():
    p = build_base_system_prompt('t', 's', 'r', include_sot=False)
    assert 'README alignment' in p and 'READ MME' not in p

def test_both_auth_endpoints_respond(client):
    assert client.post('/api/auth/login').status_code in (400, 401)
    assert client.post('/auth/login').status_code in (400, 401)
